/*!
 * respysive runtime — slide navigation, fragments, overflow fitting,
 * speaker view and print layout for respysive-slide presentations.
 *
 * DOM contract (generated by respysive.presentation):
 *   <div class="reveal rs-deck">
 *     <div class="slides rs-canvas">
 *       <section class="rs-slide">…</section>              horizontal slide
 *       <section class="stack">                            vertical stack
 *         <section class="rs-slide">…</section>
 *       </section>
 *
 * Each leaf slide holds an optional <div class="rs-bg"> background layer,
 * a <div class="rs-body"> content box and optional <aside class="notes">.
 */
(function () {
  'use strict';

  var cfg = Object.assign({
    width: 1280,
    height: 720,
    margin: 0.04,
    minScale: 0.2,
    maxScale: 2.0,
    transition: 'slide',
    overflow: 'fit',
    minFontScale: 0.6,
    controls: true,
    progress: true,
    slideNumber: 'c/t',
    embedded: false
  }, window.RESPYSIVE_CONFIG || {});

  var W = cfg.width, H = cfg.height;
  var params = new URLSearchParams(location.search);
  var MODE = params.has('rs-speaker') ? 'speaker'
    : params.has('rs-preview') ? 'preview'
    : params.has('print-pdf') ? 'print'
    : 'main';

  var root = document.documentElement;
  var deck, canvas;
  var grid = [];          // grid[h] = [leaf section, …]
  var flat = [];          // leaf sections in linear reading order
  var state = { h: 0, v: 0, f: -1 };
  var current = null;
  var scale = 1;
  var overview = false;
  var speakerWin = null;
  var listeners = {};
  var readyResolve;
  var ready = new Promise(function (resolve) { readyResolve = resolve; });

  // ---------------------------------------------------------------- events

  function emit(name, detail) {
    (listeners[name] || []).forEach(function (fn) {
      try { fn(detail); } catch (e) { console.error(e); }
    });
    document.dispatchEvent(new CustomEvent('rs:' + name, { detail: detail }));
  }

  function on(name, fn) {
    (listeners[name] = listeners[name] || []).push(fn);
  }

  // ------------------------------------------------------------- structure

  function collect() {
    grid = [];
    flat = [];
    Array.prototype.forEach.call(canvas.children, function (top) {
      if (top.tagName !== 'SECTION') return;
      var subs = Array.prototype.filter.call(top.children, function (c) { return c.tagName === 'SECTION'; });
      var column = subs.length ? subs : [top];
      if (subs.length) top.classList.add('stack');
      var h = grid.length;
      column.forEach(function (s, v) {
        s.classList.add('rs-slide');
        s.dataset.rsH = h;
        s.dataset.rsV = v;
        s.dataset.rsIndex = flat.length;
        flat.push(s);
      });
      grid.push(column);
    });
    if (flat.length) flat[flat.length - 1].classList.add('rs-last');
  }

  function expandFragmentItems(slide) {
    slide.querySelectorAll('.fragment-items').forEach(function (box) {
      var extra = (box.dataset.fragmentStyle || '').split(/\s+/).filter(Boolean);
      box.querySelectorAll('li').forEach(function (li) {
        li.classList.add('fragment');
        extra.forEach(function (c) { li.classList.add(c); });
      });
    });
  }

  // Fragments sharing a data-fragment-index form one step; fragments
  // without an index each form their own step, after indexed ones.
  function fragmentGroups(slide) {
    if (slide._rsGroups) return slide._rsGroups;
    var indexed = {}, loose = [];
    slide.querySelectorAll('.fragment').forEach(function (el) {
      if (el.hasAttribute('data-fragment-index')) {
        var i = parseInt(el.getAttribute('data-fragment-index'), 10);
        (indexed[i] = indexed[i] || []).push(el);
      } else {
        loose.push([el]);
      }
    });
    var keys = Object.keys(indexed).map(Number).sort(function (a, b) { return a - b; });
    slide._rsGroups = keys.map(function (k) { return indexed[k]; }).concat(loose);
    return slide._rsGroups;
  }

  function applyFragments(slide, f) {
    fragmentGroups(slide).forEach(function (group, i) {
      group.forEach(function (el) {
        el.classList.toggle('visible', i <= f);
        el.classList.toggle('current-fragment', i === f);
      });
    });
  }

  // ------------------------------------------------------------ navigation

  function clampState(h, v, f) {
    h = Math.max(0, Math.min(grid.length - 1, h | 0));
    v = Math.max(0, Math.min(grid[h].length - 1, v | 0));
    var n = fragmentGroups(grid[h][v]).length;
    if (f === 'last') f = n - 1;
    f = (f === undefined || f === null) ? -1 : Math.max(-1, Math.min(n - 1, f | 0));
    return { h: h, v: v, f: f };
  }

  function go(h, v, f, silent) {
    if (!grid.length) return;
    var next = clampState(h, v, f);
    var previous = current;
    var slideChanged = !previous || next.h !== state.h || next.v !== state.v;
    var fragmentChanged = next.f !== state.f;
    state = next;
    current = grid[state.h][state.v];

    grid.forEach(function (column, ch) {
      column.forEach(function (s, cv) {
        var pos;
        if (ch === state.h && cv === state.v) pos = 'present';
        else if (ch === state.h) pos = cv < state.v ? 'past-v' : 'future-v';
        else pos = ch < state.h ? 'past' : 'future';
        s.classList.remove('present', 'past', 'future', 'past-v', 'future-v');
        s.classList.add(pos);
        s.setAttribute('aria-hidden', pos === 'present' ? 'false' : 'true');
        if (pos !== 'present') {
          // slides left behind keep their fragments fully shown, slides ahead reset
          applyFragments(s, (pos === 'past' || pos === 'past-v') ? fragmentGroups(s).length - 1 : -1);
        }
      });
    });
    applyFragments(current, state.f);

    flat.forEach(function (s) {
      if (s._rsBgView) s._rsBgView.classList.toggle('present', s === current);
    });

    // letterbox areas around the canvas take the slide background colour
    var bg = current.querySelector(':scope > .rs-bg');
    deck.style.backgroundColor = bg ? getComputedStyle(bg).backgroundColor : '';

    updateChrome();
    if (overview) layoutOverview();
    if (MODE === 'main' && !cfg.embedded) {
      var hash = '#/' + state.h + (state.v || state.f >= 0 ? '/' + state.v : '') + (state.f >= 0 ? '/' + state.f : '');
      // srcdoc and sandboxed iframes have no URL to update: navigation still works
      if (location.hash !== hash) {
        try { history.replaceState(null, '', hash); } catch (e) { /* no history */ }
      }
    }
    if (silent) return;
    if (slideChanged) emit('slidechanged', { h: state.h, v: state.v, f: state.f, slide: current, previous: previous });
    if (fragmentChanged) emit('fragmentchanged', { h: state.h, v: state.v, f: state.f, slide: current });
    broadcast();
  }

  function stepNext(s) {
    var n = fragmentGroups(grid[s.h][s.v]).length;
    if (s.f < n - 1) return { h: s.h, v: s.v, f: s.f + 1 };
    if (s.v < grid[s.h].length - 1) return { h: s.h, v: s.v + 1, f: -1 };
    if (s.h < grid.length - 1) return { h: s.h + 1, v: 0, f: -1 };
    return null;
  }

  function stepPrev(s) {
    if (s.f >= 0) return { h: s.h, v: s.v, f: s.f - 1 };
    if (s.v > 0) return { h: s.h, v: s.v - 1, f: 'last' };
    if (s.h > 0) return { h: s.h - 1, v: grid[s.h - 1].length - 1, f: 'last' };
    return null;
  }

  function hasNextFragment() { return state.f < fragmentGroups(current).length - 1; }

  var commands = {
    next: function () { var s = stepNext(state); if (s) go(s.h, s.v, s.f); },
    prev: function () { var s = stepPrev(state); if (s) go(s.h, s.v, s.f); },
    right: function () {
      if (!overview && hasNextFragment()) return go(state.h, state.v, state.f + 1);
      if (state.h < grid.length - 1) go(state.h + 1, 0, -1);
    },
    left: function () {
      if (!overview && state.f >= 0) return go(state.h, state.v, state.f - 1);
      if (state.h > 0) go(state.h - 1, 0, overview ? -1 : 'last');
    },
    down: function () {
      if (!overview && hasNextFragment()) return go(state.h, state.v, state.f + 1);
      if (state.v < grid[state.h].length - 1) go(state.h, state.v + 1, -1);
    },
    up: function () {
      if (!overview && state.f >= 0) return go(state.h, state.v, state.f - 1);
      if (state.v > 0) go(state.h, state.v - 1, overview ? -1 : 'last');
    },
    first: function () { go(0, 0, -1); },
    last: function () { var h = grid.length - 1; go(h, grid[h].length - 1, 'last'); },
    overview: function () { toggleOverview(); },
    blackout: function () { root.classList.toggle('rs-blackout'); },
    fullscreen: function () {
      if (document.fullscreenElement) document.exitFullscreen();
      else (cfg.embedded ? deck : root).requestFullscreen().catch(function () {});
    },
    speaker: function () { openSpeaker(); }
  };

  function exec(cmd) {
    if (MODE === 'speaker') {
      if (window.opener) window.opener.postMessage({ type: 'rs-command', cmd: cmd }, '*');
      return;
    }
    if (commands[cmd]) commands[cmd]();
  }

  var KEYMAP = {
    ArrowRight: 'right', ArrowLeft: 'left', ArrowDown: 'down', ArrowUp: 'up',
    l: 'right', h: 'left', j: 'down', k: 'up',
    ' ': 'next', PageDown: 'next', n: 'next', Enter: 'next',
    PageUp: 'prev', p: 'prev', Backspace: 'prev',
    Home: 'first', End: 'last',
    Escape: 'overview', o: 'overview',
    b: 'blackout', '.': 'blackout',
    f: 'fullscreen', s: 'speaker'
  };

  function onKey(e) {
    if (e.altKey || e.ctrlKey || e.metaKey) return;
    var t = e.target;
    if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
    var cmd = KEYMAP[e.key];
    if (!cmd) return;
    if (overview && (cmd === 'next' && e.key === 'Enter')) cmd = 'overview';
    if (MODE === 'speaker' && cmd === 'speaker') return;
    e.preventDefault();
    exec(cmd);
  }

  function bindTouch() {
    var x0 = null, y0 = null;
    deck.addEventListener('touchstart', function (e) {
      if (e.touches.length !== 1 || e.target.closest('.maplibregl-map, .js-plotly-plot, canvas, .rs-no-swipe')) {
        x0 = null;
        return;
      }
      x0 = e.touches[0].clientX;
      y0 = e.touches[0].clientY;
    }, { passive: true });
    deck.addEventListener('touchend', function (e) {
      if (x0 === null) return;
      var dx = e.changedTouches[0].clientX - x0, dy = e.changedTouches[0].clientY - y0;
      x0 = null;
      if (Math.max(Math.abs(dx), Math.abs(dy)) < 40) return;
      if (Math.abs(dx) > Math.abs(dy)) exec(dx < 0 ? 'right' : 'left');
      else exec(dy < 0 ? 'down' : 'up');
    });
  }

  function readHash() {
    var parts = location.hash.replace(/^#\/?/, '').split('/').filter(Boolean);
    if (!parts.length) return null;
    if (/^\d+$/.test(parts[0])) {
      return { h: +parts[0], v: parts[1] ? +parts[1] : 0, f: parts[2] !== undefined ? +parts[2] : -1 };
    }
    var target = document.getElementById(decodeURIComponent(parts[0]));
    var slide = target && target.closest('.rs-slide');
    return slide ? { h: +slide.dataset.rsH, v: +slide.dataset.rsV, f: -1 } : null;
  }

  // ---------------------------------------------------------------- chrome

  var chrome = {};

  function buildChrome() {
    if (cfg.controls) {
      var arrow = function (dir, d) {
        return '<button class="navigate-' + dir + '" data-cmd="' + dir + '" aria-label="' + dir + '">' +
          '<svg viewBox="0 0 24 24"><path d="' + d + '"/></svg></button>';
      };
      chrome.controls = document.createElement('aside');
      chrome.controls.className = 'controls';
      chrome.controls.innerHTML =
        arrow('left', 'M15 5 8 12l7 7') + arrow('right', 'M9 5l7 7-7 7') +
        arrow('up', 'M5 15l7-7 7 7') + arrow('down', 'M5 9l7 7 7-7');
      chrome.controls.addEventListener('click', function (e) {
        var b = e.target.closest('button');
        if (b) exec(b.dataset.cmd);
      });
      deck.appendChild(chrome.controls);
    }
    if (cfg.progress) {
      chrome.progress = document.createElement('div');
      chrome.progress.className = 'progress';
      chrome.progress.innerHTML = '<span></span>';
      deck.appendChild(chrome.progress);
    }
    if (cfg.slideNumber) {
      chrome.number = document.createElement('div');
      chrome.number.className = 'slide-number';
      deck.appendChild(chrome.number);
    }
  }

  function slideNumberText() {
    var idx = +current.dataset.rsIndex + 1;
    switch (cfg.slideNumber) {
      case 'h.v': return (state.h + 1) + (state.v ? '.' + (state.v + 1) : '');
      case 'h/v': return (state.h + 1) + (state.v ? '/' + (state.v + 1) : '');
      case 'c': return String(idx);
      default: return idx + ' / ' + flat.length;
    }
  }

  function updateChrome() {
    if (chrome.controls) {
      var en = {
        left: state.h > 0 || state.f >= 0,
        right: state.h < grid.length - 1 || hasNextFragment(),
        up: state.v > 0 || state.f >= 0,
        down: state.v < grid[state.h].length - 1 || hasNextFragment()
      };
      Object.keys(en).forEach(function (dir) {
        chrome.controls.querySelector('.navigate-' + dir).classList.toggle('enabled', en[dir]);
      });
    }
    if (chrome.progress) {
      var total = Math.max(1, flat.length - 1);
      chrome.progress.firstChild.style.transform = 'scaleX(' + (+current.dataset.rsIndex / total) + ')';
    }
    if (chrome.number) chrome.number.textContent = slideNumberText();
  }

  // Copy each slide background into a layer covering the whole deck, as
  // Reveal.js does, so images reach the window edges instead of stopping at
  // the canvas margin.
  function buildBackgrounds() {
    var layer = document.createElement('div');
    layer.className = 'rs-backgrounds';
    flat.forEach(function (slide) {
      var bg = slide.querySelector(':scope > .rs-bg');
      if (!bg) return;
      var view = document.createElement('div');
      view.className = 'rs-bg-view';
      view.appendChild(bg.cloneNode(true));
      layer.appendChild(view);
      slide._rsBgView = view;
    });
    if (!layer.children.length) return;
    deck.insertBefore(layer, deck.firstChild);
    root.classList.add('rs-viewport-bg');
  }

  // ---------------------------------------------------------------- layout

  function deckSize() {
    if (cfg.embedded) {
      var r = deck.getBoundingClientRect();
      return { w: r.width, h: r.height };
    }
    return { w: window.innerWidth, h: window.innerHeight };
  }

  // A transform (not CSS zoom) keeps the layout computed at the slide's
  // native size: line breaks, and therefore overflow fitting, are the same
  // whatever the window size, and the same as in the PDF.
  function setCanvasScale(s) {
    canvas.style.transform = 'scale(' + s + ')';
  }

  function layout() {
    if (MODE === 'print' || root.classList.contains('rs-print')) return;
    var size = deckSize();
    var m = 1 - cfg.margin;
    scale = Math.min(size.w * m / W, size.h * m / H);
    scale = Math.max(cfg.minScale, Math.min(cfg.maxScale, scale));
    if (overview) layoutOverview();
    else setCanvasScale(scale);
  }

  // ------------------------------------------------------- overflow fitting

  // Height needed by the body, as a ratio of the height available inside the
  // slide. Uses bounding rects of both elements so the result is unaffected
  // by the canvas transform.
  function overflowRatio(slide, body) {
    var sr = slide.getBoundingClientRect();
    if (!sr.height) return 1;
    var cs = getComputedStyle(slide);
    var avail = H - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
    var need = body.getBoundingClientRect().height / sr.height * H;
    return need / avail;
  }

  var FIT_TOLERANCE = 1.01;

  // Reveal.js r-fit-text: font size that makes the text fill the width of its
  // parent on one line (as fitty does). Layout sizes, so the canvas transform
  // does not matter; a few passes absorb padding that does not scale.
  function fitText(slide) {
    slide.querySelectorAll('.r-fit-text').forEach(function (el) {
      var parent = el.parentNode;
      for (var i = 0; i < 3; i++) {
        var avail = parent.clientWidth, width = el.scrollWidth;
        if (!avail || !width) return;
        var size = parseFloat(getComputedStyle(el).fontSize);
        var next = Math.min(Math.max(12, size * avail / width), H * 0.8);
        if (Math.abs(next - size) < 0.5) return;
        el.style.fontSize = next + 'px';
      }
    });
  }

  function fitSlide(slide) {
    var body = slide.querySelector(':scope > .rs-body');
    if (!body) return;
    var mode = slide.dataset.overflow || cfg.overflow;
    body.style.removeProperty('--rs-fit');
    body.style.zoom = '';
    body.style.width = '';
    body.style.alignSelf = '';
    delete slide.dataset.rsFit;
    delete slide.dataset.rsZoom;
    delete slide.dataset.rsOverflow;
    fitText(slide);
    if (mode !== 'fit' && mode !== 'warn') return;

    var ratio = overflowRatio(slide, body);
    // Sub-pixel rounding varies with the window size; a slight excess only
    // eats into the slide padding, so ignore it to keep fitting stable.
    if (ratio <= FIT_TOLERANCE) return;
    if (mode === 'warn') {
      slide.dataset.rsOverflow = ratio.toFixed(3);
      console.warn('[respysive] slide ' + slide.dataset.rsH + '.' + slide.dataset.rsV +
        ' overflows by ' + Math.round((ratio - 1) * 100) + '%');
      return;
    }

    // 1. shrink text, like PowerPoint's "shrink text on overflow"
    var lo = cfg.minFontScale, hi = 1;
    body.style.setProperty('--rs-fit', lo);
    if (overflowRatio(slide, body) <= 1) {
      for (var i = 0; i < 7; i++) {
        var mid = (lo + hi) / 2;
        body.style.setProperty('--rs-fit', mid);
        if (overflowRatio(slide, body) <= 1) lo = mid; else hi = mid;
      }
      body.style.setProperty('--rs-fit', lo.toFixed(3));
      slide.dataset.rsFit = lo.toFixed(3);
      return;
    }

    // 2. text alone is not enough (charts, images…): scale the whole body.
    // Zooming widens the body in its own coordinates, so content reflows and
    // 1/ratio always fits; search the largest zoom that still fits.
    body.style.removeProperty('--rs-fit');
    var zlo = 1 / ratio, zhi = 1;
    for (var j = 0; j < 8; j++) {
      var z = (zlo + zhi) / 2;
      body.style.zoom = z;
      if (overflowRatio(slide, body) <= 1) zlo = z; else zhi = z;
    }
    body.style.zoom = zlo.toFixed(3);

    // 3. content sized by the width (images, charts in % width) grows back as
    // the zoomed body widens, so the search above may not fit. Then scale
    // uniformly: pin the body width so the layout stays the native one.
    if (overflowRatio(slide, body) > FIT_TOLERANCE) {
      body.style.zoom = '';
      var width = body.offsetWidth;
      ratio = overflowRatio(slide, body);
      body.style.width = width + 'px';
      body.style.alignSelf = 'center';
      zlo = Math.floor(1000 / ratio) / 1000;
      body.style.zoom = zlo;
    }
    slide.dataset.rsZoom = zlo.toFixed(3);
    if (zlo < 0.5) {
      console.warn('[respysive] slide ' + slide.dataset.rsH + '.' + slide.dataset.rsV +
        ' scaled to ' + Math.round(zlo * 100) + '% to fit: consider splitting it');
    }
  }

  var fitQueue = new Set(), fitScheduled = false;

  function scheduleFit(slide) {
    fitQueue.add(slide);
    if (fitScheduled) return;
    fitScheduled = true;
    requestAnimationFrame(function () {
      fitScheduled = false;
      var slides = Array.from(fitQueue);
      fitQueue.clear();
      slides.forEach(fitSlide);
    });
  }

  function fitAll() { flat.forEach(fitSlide); }

  function overflowReport() {
    return flat.filter(function (s) {
      return s.dataset.rsFit || s.dataset.rsZoom || s.dataset.rsOverflow;
    }).map(function (s) {
      var report = {
        h: +s.dataset.rsH, v: +s.dataset.rsV,
        fontScale: s.dataset.rsFit ? +s.dataset.rsFit : 1,
        zoom: s.dataset.rsZoom ? +s.dataset.rsZoom : 1
      };
      // 'warn' mode: how much taller than the slide the content is
      if (s.dataset.rsOverflow) report.overflow = +s.dataset.rsOverflow;
      return report;
    });
  }

  // -------------------------------------------------------------- overview

  function layoutOverview() {
    var s = scale * 0.22;
    setCanvasScale(s);
    flat.forEach(function (slide) {
      var dx = (+slide.dataset.rsH - state.h) * W * 1.1;
      var dy = (+slide.dataset.rsV - state.v) * H * 1.1;
      slide.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
    });
  }

  function toggleOverview(force) {
    overview = force === undefined ? !overview : force;
    root.classList.toggle('rs-overview', overview);
    if (overview) {
      layoutOverview();
    } else {
      flat.forEach(function (slide) { slide.style.transform = ''; });
      layout();
    }
    emit('overview', { active: overview });
  }

  function bindOverviewClicks() {
    canvas.addEventListener('click', function (e) {
      if (!overview) return;
      var slide = e.target.closest('.rs-slide');
      if (!slide) return;
      e.preventDefault();
      go(+slide.dataset.rsH, +slide.dataset.rsV, -1);
      toggleOverview(false);
    }, true);
  }

  // --------------------------------------------------------- speaker view

  function baseUrl() { return location.href.split('#')[0].split('?')[0]; }

  function hashOf(s) { return '#/' + s.h + '/' + s.v + '/' + s.f; }

  function openSpeaker() {
    if (speakerWin && !speakerWin.closed) { speakerWin.focus(); return; }
    speakerWin = window.open(baseUrl() + '?rs-speaker' + hashOf(state), 'rs-speaker',
      'width=1280,height=760');
  }

  function broadcast() {
    if (MODE !== 'main' || !speakerWin || speakerWin.closed) return;
    var nxt = stepNext(state);
    speakerWin.postMessage({ type: 'rs-state', state: state, next: nxt, total: flat.length }, '*');
  }

  function notesOf(slide) {
    var html = Array.prototype.map.call(slide.querySelectorAll('aside.notes'), function (a) {
      return a.innerHTML;
    }).join('');
    return html || '<p class="rs-sp-empty">No notes for this slide.</p>';
  }

  function buildSpeaker() {
    root.classList.add('rs-speaker-mode');
    var ui = document.createElement('div');
    ui.className = 'rs-speaker';
    var src = baseUrl() + '?rs-preview';
    ui.innerHTML =
      '<div class="rs-sp-current"><iframe title="Current slide"></iframe></div>' +
      '<div class="rs-sp-side">' +
      '  <div class="rs-sp-label">Next</div>' +
      '  <div class="rs-sp-next"><iframe title="Next slide"></iframe><div class="rs-sp-end">End of presentation</div></div>' +
      '  <div class="rs-sp-info"><span class="rs-sp-timer" title="Click to reset">00:00:00</span>' +
      '    <span class="rs-sp-clock"></span><span class="rs-sp-num"></span></div>' +
      '  <div class="rs-sp-notes"></div>' +
      '</div>';
    document.body.appendChild(ui);

    var cur = ui.querySelector('.rs-sp-current iframe');
    var nxt = ui.querySelector('.rs-sp-next iframe');
    var initial = readHash() || state;
    cur.src = src + hashOf(initial);
    nxt.src = src + hashOf(stepNext(clampState(initial.h, initial.v, initial.f)) || initial);

    var start = Date.now();
    var timer = ui.querySelector('.rs-sp-timer');
    timer.addEventListener('click', function () { start = Date.now(); });
    var pad = function (n) { return (n < 10 ? '0' : '') + n; };
    setInterval(function () {
      var t = Math.floor((Date.now() - start) / 1000);
      timer.textContent = pad(Math.floor(t / 3600)) + ':' + pad(Math.floor(t / 60) % 60) + ':' + pad(t % 60);
      var d = new Date();
      ui.querySelector('.rs-sp-clock').textContent = pad(d.getHours()) + ':' + pad(d.getMinutes());
    }, 500);

    var post = function (frame, s) {
      if (frame.contentWindow) frame.contentWindow.postMessage({ type: 'rs-goto', state: s }, '*');
    };
    window.addEventListener('message', function (e) {
      if (e.source !== window.opener || !e.data || e.data.type !== 'rs-state') return;
      var s = e.data.state, n = e.data.next;
      post(cur, s);
      ui.querySelector('.rs-sp-next').classList.toggle('rs-sp-done', !n);
      if (n) post(nxt, n);
      ui.querySelector('.rs-sp-notes').innerHTML = notesOf(grid[s.h][s.v]);
      ui.querySelector('.rs-sp-num').textContent = (+grid[s.h][s.v].dataset.rsIndex + 1) + ' / ' + e.data.total;
    });
    document.addEventListener('keydown', onKey);
    if (window.opener) window.opener.postMessage({ type: 'rs-speaker-ready' }, '*');
  }

  function bindMessages() {
    window.addEventListener('message', function (e) {
      var d = e.data;
      if (!d || typeof d.type !== 'string' || d.type.indexOf('rs-') !== 0) return;
      if (MODE === 'main' && e.source === speakerWin) {
        if (d.type === 'rs-speaker-ready') broadcast();
        else if (d.type === 'rs-command' && commands[d.cmd] && d.cmd !== 'speaker') commands[d.cmd]();
      } else if (MODE === 'preview' && e.source === window.parent && d.type === 'rs-goto') {
        go(d.state.h, d.state.v, d.state.f, true);
      }
    });
  }

  // ----------------------------------------------------------------- print

  function enterPrint() {
    root.classList.add('rs-print');
    canvas.style.transform = '';
    flat.forEach(function (s) { applyFragments(s, fragmentGroups(s).length - 1); });
    fitAll();
  }

  function exitPrint() {
    root.classList.remove('rs-print');
    go(state.h, state.v, state.f, true);
    layout();
    fitAll();
  }

  // One printed page per fragment step: each slide with fragments is preceded
  // by static copies showing its earlier steps. Call it once charts are drawn,
  // since copies are not re-rendered (map iframes excepted, they reload).
  function printSteps() {
    if (!root.classList.contains('rs-print')) enterPrint();
    var pages = 0;
    flat.forEach(function (slide) {
      var steps = fragmentGroups(slide).length;
      for (var f = -1; f < steps - 1; f++) {
        applyFragments(slide, f);
        var copy = slide.cloneNode(true);
        copy.classList.remove('rs-last');
        copy.classList.add('rs-step');
        slide.parentNode.insertBefore(copy, slide);
        pages++;
      }
      applyFragments(slide, steps - 1);
    });
    return flat.length + pages;
  }

  function waitFor(test, timeoutMs) {
    return new Promise(function (resolve) {
      var start = Date.now();
      (function poll() {
        if (test()) return resolve(true);
        if (Date.now() - start > timeoutMs) return resolve(false);
        setTimeout(poll, 100);
      })();
    });
  }

  // Plotly map subplots (choroplethmap, scattermap…) wrap a MapLibre map
  function plotlyMapsLoaded() {
    return Array.prototype.every.call(document.querySelectorAll('.js-plotly-plot'), function (gd) {
      var layout = gd._fullLayout || {};
      return Object.keys(layout).every(function (key) {
        var subplot = /^map(box)?\d*$/.test(key) && layout[key] && layout[key]._subplot;
        return !subplot || !subplot.map || subplot.map.loaded();
      });
    });
  }

  // Maps are drawn once their iframe flags the MapLibre 'idle' event
  function mapsIdle() {
    if (!plotlyMapsLoaded()) return false;
    return Array.prototype.every.call(document.querySelectorAll('iframe'), function (frame) {
      try {
        var doc = frame.contentDocument;
        return !doc || !doc.querySelector('.maplibregl-map') || doc.documentElement.hasAttribute('data-rs-idle');
      } catch (e) {
        return true;  // cross-origin frame: nothing to wait for
      }
    });
  }

  // Resolves when the deck is ready to be captured (PDF, PPTX)
  function settled(timeoutMs) {
    timeoutMs = timeoutMs || 30000;
    var waits = [ready, waitFor(mapsIdle, timeoutMs)];
    if (window.MathJax && window.MathJax.startup && window.MathJax.startup.promise) {
      waits.push(window.MathJax.startup.promise);
    }
    return Promise.all(waits).then(function (results) {
      if (!results[1]) console.warn('[respysive] maps still loading after ' + timeoutMs + ' ms');
      fitAll();
      return new Promise(function (resolve) {
        requestAnimationFrame(function () { requestAnimationFrame(resolve); });
      });
    }).then(function () { return overflowReport(); });
  }

  // -------------------------------------------------------- integrations

  on('slidechanged', function (e) {
    if (window.Plotly && window.Plotly.Plots) {
      e.slide.querySelectorAll('.js-plotly-plot').forEach(function (el) {
        try { window.Plotly.Plots.resize(el); } catch (err) { /* chart not ready */ }
      });
    }
    if (window.MathJax && window.MathJax.typesetPromise) {
      window.MathJax.typesetPromise([e.slide]).catch(function () {});
    }
  });

  // ------------------------------------------------------------------ init

  function init() {
    deck = document.querySelector('.rs-deck');
    canvas = deck && deck.querySelector('.rs-canvas');
    if (!canvas) return;
    root.classList.add('rs-mode-' + MODE, 'rs-transition-' + (MODE === 'preview' ? 'none' : cfg.transition));
    if (cfg.embedded) root.classList.add('rs-embedded');
    collect();
    if (!grid.length) return;
    flat.forEach(expandFragmentItems);
    bindMessages();

    if (MODE === 'speaker') {
      buildSpeaker();
      return;
    }
    if (MODE !== 'print') buildBackgrounds();
    if (MODE === 'main') {
      buildChrome();
      if (cfg.embedded) {
        deck.tabIndex = 0;
        deck.addEventListener('keydown', onKey);
      } else {
        document.addEventListener('keydown', onKey);
      }
      bindTouch();
      bindOverviewClicks();
      window.addEventListener('hashchange', function () {
        var s = readHash();
        if (s && (s.h !== state.h || s.v !== state.v || s.f !== state.f)) go(s.h, s.v, s.f);
      });
    }

    var start = readHash() || { h: 0, v: 0, f: -1 };
    go(start.h, start.v, start.f);

    if (MODE === 'print') enterPrint();
    window.addEventListener('beforeprint', function () { if (MODE !== 'print') enterPrint(); });
    window.addEventListener('afterprint', function () { if (MODE !== 'print') exitPrint(); });
    window.addEventListener('resize', layout);
    layout();

    if (window.ResizeObserver) {
      var ro = new ResizeObserver(function (entries) {
        entries.forEach(function (en) { scheduleFit(en.target.parentNode); });
      });
      flat.forEach(function (s) {
        var body = s.querySelector(':scope > .rs-body');
        if (body) ro.observe(body);
      });
    }

    var fontsReady = document.fonts && document.fonts.ready ? document.fonts.ready : Promise.resolve();
    var loaded = document.readyState === 'complete' ? Promise.resolve()
      : new Promise(function (r) { window.addEventListener('load', r, { once: true }); });
    Promise.all([fontsReady, loaded]).then(function () {
      fitAll();
      readyResolve({ slides: flat.length, overflow: overflowReport() });
      emit('ready', { slides: flat.length });
    });
  }

  window.respysive = {
    config: cfg,
    mode: MODE,
    on: on,
    go: function (h, v, f) { go(h, v, f); },
    next: function () { exec('next'); },
    prev: function () { exec('prev'); },
    state: function () { return { h: state.h, v: state.v, f: state.f }; },
    slides: function () { return flat.slice(); },
    layout: layout,
    refit: fitAll,
    overflowReport: overflowReport,
    ready: ready,
    settled: settled,
    printSteps: printSteps
  };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
